def to_floatable(x: DataArray) -> DataArray:
    if x.dtype.kind == "M":
        # datetimes
        return x.copy(
            data=datetime_to_numeric(
                x.data,
                offset=np.datetime64("1970-01-01"),
                datetime_unit="ns",
            ),
        )
    elif x.dtype.kind == "m":
        # timedeltas
        return x.astype(float)
    return x

